// Preview-only payout statements and the admin Due list. Every amount comes
// from fixtures generated by the real API services (../fixtures/payoutStatements),
// renamed onto the fictional demo organization. Nothing is saved anywhere.
//
// Click-through on a deploy preview:
//   Organizer → Finances → "Payout statement" on each "(demo)" past event
//   (Waiting for payout, Paid — reserve held, Final, Final with a balance owed),
//   or "View statement" on a payout; the open demo event shows "Sales open".
//   Admin → Payouts → Due: hold the reserve, finalize, request the payout,
//   release a reserve. Each step only changes in-memory state.
import { created, json, notFound, unprocessable } from './respond'
import { organizationFinances } from '../staff/responses'
import { DEMO_ORG_ID, DEMO_ORGANIZATION } from '../staff/fixtures'
import {
  dueFirst, dueRelease, finalNegative, finalPaid, reserveHeld, salesOpen, waitingForPayout,
} from '../fixtures/payoutStatements'

export const DEMO_PAYOUT_SENTINEL = 'HAFAPASS_DEMO_PAYOUT_SENTINEL'

const PAST_EVENTS = [
  { id: 9311, title: 'Isla Demo Grappling Open — Day 1 (demo)', statement: waitingForPayout, day: '2027-01-30' },
  { id: 9312, title: 'Isla Demo Spectator Night (demo)', statement: reserveHeld, day: '2027-01-30' },
  { id: 9313, title: 'Isla Demo Kids Cup (demo)', statement: finalPaid, day: '2027-01-30' },
  { id: 9314, title: 'Isla Demo Night Market Showcase — a very long fictional event name to test wrapping (demo)', statement: finalNegative, day: '2027-01-30' },
]
const clone = value => JSON.parse(JSON.stringify(value))

// One statement per demo event, renamed onto the demo organization; payout ids
// are made unique per event so "View statement" links resolve.
function statementFor(event, source) {
  const statement = clone(source)
  statement.event = { ...statement.event, id: event.id, title: event.title, slug: `demo-${event.id}` }
  statement.organization = { id: DEMO_ORG_ID, name: DEMO_ORGANIZATION.name }
  statement.demo_marker = DEMO_PAYOUT_SENTINEL
  statement.transfers = statement.transfers.map((transfer, index) => ({ ...transfer, id: event.id * 10 + index }))
  if (statement.payout) statement.payout = { ...statement.payout, id: event.id * 10 }
  return statement
}

function ensureState(state) {
  if (state.payouts) return state.payouts
  const staff = state.staff
  const template = staff.events[0]
  const past = PAST_EVENTS.map(spec => ({
    ...clone(template), id: spec.id, title: spec.title, slug: `demo-${spec.id}`, status: 'completed', sales_status: 'ended',
    starts_at: `${spec.day}T09:00:00+10:00`, ends_at: `${spec.day}T18:00:00+10:00`, doors_open_at: `${spec.day}T08:00:00+10:00`,
  }))
  staff.events.push(...past.filter(event => !staff.events.some(existing => existing.id === event.id)))
  const statements = Object.fromEntries(PAST_EVENTS.map((spec, index) => [spec.id, statementFor(past[index], spec.statement)]))
  if (template) statements[template.id] = statementFor(template, salesOpen)
  state.payouts = { statements, due: buildDue(), nextSettlement: 9800 }
  return state.payouts
}

function buildDue() {
  const rename = (row, event) => ({ ...clone(row), event: { ...row.event, id: event.id, title: event.title, slug: `demo-${event.id}` },
    organization: { id: DEMO_ORG_ID, name: DEMO_ORGANIZATION.name } })
  const first = rename(dueFirst.transfers[0], PAST_EVENTS[0])
  const overdue = { ...clone(dueRelease.transfers[0]), organization: { id: 9002, name: 'Example Volleyball Club of the Northern Pacific Islands (demo)' },
    event: { ...dueRelease.transfers[0].event, id: 9320, title: dueRelease.transfers[0].event.title + ' (demo)' } }
  const reserve = rename(dueRelease.reserves[0], PAST_EVENTS[1])
  return { rules: dueFirst.rules, transfers: [overdue, first], reserves: [reserve] }
}

function dueResponse(store, params) {
  const { due } = store
  const all = [...due.transfers, ...due.reserves]
  const pick = rows => params.get('filter') === 'due_now' ? rows.filter(row => ['due', 'overdue'].includes(row.due_state)) : rows
  return {
    generated_at: new Date().toISOString(), rules: due.rules, demo_marker: DEMO_PAYOUT_SENTINEL,
    counts: ['overdue', 'due', 'upcoming'].reduce((counts, key) => ({ ...counts, [key]: all.filter(row => row.due_state === key).length }), {}),
    transfers: pick(due.transfers), reserves: pick(due.reserves),
  }
}

const findRow = (store, eventId) => [...store.due.transfers, ...store.due.reserves].find(row => String(row.event.id) === String(eventId))

function csv(statement) {
  const cell = value => `"${String(value ?? '').replaceAll('"', '""')}"`
  const money = cents => (cents == null ? '' : (cents / 100).toFixed(2))
  const rows = [['section', 'line', 'amount', 'note'], ['Statement', 'Event', '', statement.event.title], ['Statement', 'Status', '', statement.status_label]]
  statement.sections.forEach(section => {
    section.lines.forEach(line => rows.push([section.title, line.label, money(line.amount_cents), line.note]))
    rows.push([section.title, section.total_label, money(section.total_cents), ''])
  })
  rows.push(['Balance', 'Balance remaining', money(statement.totals.balance_remaining_cents), ''])
  return new Blob([rows.map(row => row.map(cell).join(',')).join('\n')], { type: 'text/csv' })
}

function eventFinance(statement) {
  const { totals } = statement
  return {
    preview: { currency: 'usd', gross_cents: totals.gross_cents, refund_cents: 0, processing_fee_cents: 0, platform_processing_fee_cents: 0,
      payable_cents: Math.max(totals.available_cents, 0), negative_balance_cents: Math.max(-totals.balance_remaining_cents, 0), paid_cents: totals.transferred_cents },
    settlements: [],
    payouts: statement.transfers.map(transfer => ({ id: transfer.id, provider: 'manual', status: transfer.status, amount_cents: transfer.amount_cents })),
    connected_account: { provider: 'manual', payout_ready: true },
  }
}

export async function handle({ method, path, params, state, body }) {
  if (!state.staff) return undefined
  const store = ensureState(state)

  const statementPath = path.match(/^\/organizer\/events\/(\d+)\/finance\/payout_statement(_export)?$/)
  if (method === 'get' && statementPath) {
    const statement = store.statements[statementPath[1]]
    if (!statement) return notFound('This demo event has no payout statement.')
    if (statementPath[2]) return json(csv(statement))
    const payoutId = params.get('payout_id')
    if (!payoutId) return json({ ...statement, payout: null })
    const transfer = statement.transfers.find(item => String(item.id) === payoutId)
    if (!transfer) return notFound('Payout not found')
    const { counted_cents: _counted, ...rest } = transfer
    return json({ ...statement, payout: { ...rest, version: { version: rest.statement_version || 1, net_proceeds_cents: statement.totals.net_proceeds_cents,
      reserve_held_cents: statement.totals.reserve_held_cents || 0, available_cents: rest.amount_cents, previously_sent_cents: 0 } } })
  }
  const ownEvent = path.match(/^\/organizer\/events\/(93\d\d)\/(stats|finance)$/)
  if (method === 'get' && ownEvent) {
    const statement = store.statements[ownEvent[1]]
    if (ownEvent[2] === 'finance') return json(eventFinance(statement))
    const sold = statement.sales_by_ticket.reduce((total, row) => total + row.quantity, 0)
    return json({ total_tickets_sold: sold, total_revenue_cents: statement.totals.gross_cents, tickets_checked_in: Math.round(sold * 0.8),
      tickets_by_type: statement.sales_by_ticket.map(row => ({ name: row.name, sold: row.quantity, available: 0, revenue_cents: row.gross_cents })), recent_orders: [] })
  }

  if (method === 'get' && path === '/organizer/finances') {
    const summary = organizationFinances(state.staff)
    const extra = PAST_EVENTS.map(spec => {
      const { totals } = store.statements[spec.id]
      return {
        id: spec.id, title: spec.title, slug: `demo-${spec.id}`, status: 'completed', starts_at: `${spec.day}T09:00:00+10:00`, timezone: 'Pacific/Guam',
        organizer_proceeds_cents: totals.ticket_proceeds_cents, paid_cents: totals.transferred_cents, owed_cents: Math.max(totals.balance_remaining_cents, 0),
        requestable_cents: 0, negative_balance_cents: Math.max(-totals.balance_remaining_cents, 0), settlement: { id: spec.id, version: 1, current: true },
        settlement_state: 'finalized', payout_state: totals.balance_remaining_cents > 0 ? 'awaiting_statement' : totals.transferred_cents > 0 ? 'paid' : 'nothing_owed',
      }
    })
    const payouts = PAST_EVENTS.flatMap(spec => store.statements[spec.id].transfers.map(transfer => ({
      id: transfer.id, event_id: spec.id, event_title: spec.title, settlement_version: transfer.statement_version || 1, amount_cents: transfer.amount_cents,
      withheld_cents: 0, disbursement_cents: transfer.sent_cents, currency: 'usd', status: transfer.status, provider: 'manual', provider_payout_id: transfer.reference,
      failure_message: null, initiated_at: `${transfer.requested_on}T10:00:00+10:00`, paid_at: transfer.sent_on && `${transfer.sent_on}T15:00:00+10:00`, created_at: `${transfer.requested_on}T10:00:00+10:00`,
    })))
    return json({ ...summary, events: [...summary.events, ...extra], payouts: [...payouts, ...summary.payouts], payouts_count: summary.payouts_count + payouts.length })
  }

  if (method === 'get' && path === '/admin/payout_schedule') return json(dueResponse(store, params))
  const step = path.match(/^\/admin\/payout_schedule\/(\d+)\/(reserve|release|finalize)$/)
  if (method === 'post' && step) {
    const row = findRow(store, step[1])
    if (!row) return notFound('Event not found')
    if (step[2] === 'reserve') {
      if (!row.actions.includes('hold_reserve')) return unprocessable('A reserve is already held for this event')
      const amount = Number.isSafeInteger(body?.amount_cents) ? body.amount_cents : row.suggested_reserve_cents
      Object.assign(row, { reserve_held_cents: amount, suggested_reserve_cents: null, owed_cents: row.owed_cents - amount, next_step: 'finalize_statement',
        next_step_label: 'Finalize the statement', actions: ['finalize_statement'] })
      return created({ id: Date.now(), kind: 'reserve_hold', amount_cents: -amount })
    }
    if (step[2] === 'finalize') {
      store.nextSettlement += 1
      Object.assign(row, { settlement: { id: store.nextSettlement, version: 1, available_to_payout_cents: row.owed_cents },
        next_step: 'send_transfer', next_step_label: 'Request the payout and send the bank transfer', actions: ['send_transfer'] })
      return created({ id: store.nextSettlement, version: 1, available_to_payout_cents: row.owed_cents })
    }
    if (row.reserve_held_cents <= 0) return unprocessable('No reserve is held for this event')
    const remaining = row.after_release_cents
    store.due.reserves = store.due.reserves.filter(item => item !== row)
    Object.assign(row, { reserve_held_cents: 0, reserve_released_cents: row.reserve_held_cents, owed_cents: remaining, after_release_cents: remaining,
      next_step: remaining > 0 ? 'finalize_statement' : 'negative_balance', next_step_label: remaining > 0 ? 'Finalize the statement' : 'Organizer owes a balance',
      actions: remaining > 0 ? ['finalize_statement'] : [], due_on: '2027-03-04', due_state: 'due' })
    store.due.transfers.push(row)
    return created({ id: Date.now(), kind: 'reserve_release', amount_cents: row.reserve_released_cents })
  }
  if (method === 'post' && path === '/admin/payouts') {
    const row = store.due.transfers.find(item => item.settlement && String(item.settlement.id) === String(body?.settlement_id))
    if (!row) return undefined
    Object.assign(row, { in_flight_payout: { id: store.nextSettlement + 100, status: 'processing', amount_cents: row.settlement.available_to_payout_cents,
      disbursement_cents: row.settlement.available_to_payout_cents }, next_step: 'record_transfer', next_step_label: 'Record the bank transfer', actions: ['record_transfer'] })
    return created({ id: row.in_flight_payout.id, amount_cents: row.in_flight_payout.amount_cents, status: 'processing' })
  }
  return undefined
}
